1: //! A slice of the void-claim engine's ECS, plus two game systems that query it.
2: //!
3: //! `entity` and `world` are `void_engine::ecs` verbatim. `physics` and `render`
4: //! are the kind of systems that drive it: each walks entities holding a
5: //! particular set of components.
6: 
7: pub mod entity;
8: pub mod physics;
9: pub mod render;
10: pub mod world;
11: 
12: /// Where a thing is.
13: #[derive(Debug, Clone, Copy, PartialEq)]
14: pub struct Position {
15:     pub x: f64,
16:     pub y: f64,
17: }
18: 
19: /// How fast it is going.
20: #[derive(Debug, Clone, Copy, PartialEq)]
21: pub struct Velocity {
22:     pub dx: f64,
23:     pub dy: f64,
24: }
25: 
26: /// What it looks like.
27: #[derive(Debug, Clone, Copy, PartialEq)]
28: pub struct Sprite {
29:     pub layer: i32,
30: }
31: 
32: /// Marks an entity as frozen — it keeps its Velocity but must not move.
33: #[derive(Debug, Clone, Copy, PartialEq)]
34: pub struct Frozen;
35: 
36: /// Marks an entity as hidden — it keeps its Sprite but must not draw.
37: #[derive(Debug, Clone, Copy, PartialEq)]
38: pub struct Hidden;

